+fn dialog_gcd_k5_compress_raw_to_block(
+    b: &mut B,
+    compressed_block: &[QubitId],
+    raw_block: &[QubitId],
+    swap_host: bool,
+) {
+    assert_eq!(compressed_block.len(), 12);
+    assert_eq!(raw_block.len(), 15);
+    emit_dialog_gcd_k5_pair_encoder(b, &dialog_gcd_k5_pair01(raw_block));
+    emit_dialog_gcd_k5_pair_encoder(b, &dialog_gcd_k5_pair23(raw_block));
+    let data = dialog_gcd_k5_data_from_raw(raw_block);
+    let ancilla = b.alloc_qubit();
+    emit_dialog_gcd_k5_clean_compressor(b, &data, ancilla);
+    b.free(ancilla);
+    dialog_gcd_k5_transfer_survivors(b, compressed_block, &data, swap_host);
+}

+/// M-60 (C2b): remove the census-identified dead CCX gates (dead_t10 set) from the
+/// post-fanout op stream. Every dropped index MUST be a CCX in this build (self-check);
+/// if a build ever shifts so an index no longer points at a CCX we abort loudly rather
+/// than emit a corrupt circuit. This is the source-side port of the grinder's post-build
+/// filter, now inside `build()` so it survives an `src/point_add`-only submission.
+/// Bit-exact: the removed gates never fire for any valid curve-point input.
+/// Deep-strip: remove CCX gates verified never-firing over 1e8 inputs.
+/// Applied as the FINAL pass because the index list was derived from the final
+/// emitted stream.
+fn apply_d2_deep_strip(ops: Vec<Op>) -> Vec<Op> {
+    use std::collections::HashSet;
+    let drop: HashSet<usize> = d2_deep_strip::D2_DEEP_STRIP.iter().copied().collect();
+    ops.into_iter().enumerate().filter(|(i, _)| !drop.contains(i)).map(|(_, o)| o).collect()
+}

+// cmp window for step i: baseline is min(GAP_J2[i], current_n).
+// Delta narrows it; TRUNC_ONLY restricts narrowing to steps where the
+// baseline window is ALREADY a strict truncation (GAP_J2[i] < current_n),
+// leaving the exact-comparison tail steps untouched.
+fn cmp_window(i: usize, current_n: usize) -> usize {
+    let g = GAP_J2[i] as usize;
+    let base = g.min(current_n).max(1);
+    let d = gap_j2_delta();
+    if d == 0 {
+        return base;
+    }
+    if gap_j2_mask_trunc_only() && g >= current_n {
+        return base;
+    }
+    let lo = std::env::var("TLM_GAP_J2_LO").ok().and_then(|v| v.parse::<usize>().ok()).unwrap_or(0);
+    let hi = std::env::var("TLM_GAP_J2_HI").ok().and_then(|v| v.parse::<usize>().ok()).unwrap_or(usize::MAX);
+    if i < lo || i >= hi {
+        return base;
+    }
+    base.saturating_sub(d).max(1)
+}
